tool_input.command:
node --input-type=module -e "
import { toUtcMs } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const due_ms = toUtcMs('2026-03-01T09:00', 330); // 09:00 IST = 03:30Z
const r = { id: 1, sent: 0, tz_offset_min: 330, due_ms };
console.log('stored due_ms', new Date(due_ms).toISOString());
console.log('due at 22:00Z Feb 28 (03:30 IST)?', dueReminders([r], Date.parse('2026-02-28T22:00:00Z')).length === 1);
console.log('Intl tz ok:', new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(Date.parse('2026-03-01T17:00:00Z')));
" && node --test test/ 2>&1 | tail -8
